<?php
include __DIR__.'/addons.class.php';
require_once __DIR__.'/common.php';recibo_auth();
$s=recibo_settings();$rows=array();$summary=array();$error='';
try {$db=recibo_db();$q=$db->query('SELECT envio,COUNT(*) AS total FROM brl_pago GROUP BY envio');if($q)while($r=$q->fetch_assoc())$summary[$r['envio']]=$r['total'];
 $q=$db->query('SELECT p.*,d.http_code,d.message_id FROM brl_pago p LEFT JOIN vpscloud_recibo_delivery d ON d.queue_id=p.id ORDER BY p.data DESC,p.id DESC LIMIT 100');if($q)while($r=$q->fetch_assoc())$rows[]=$r;$db->close();}catch(Exception $e){$error=$e->getMessage();}
function rh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$labels=array(0=>'Pendente',1=>'Aceito pela API',2=>'Revisar envio',3=>'Falhou / ignorado');
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recibo Evolution</title><link href="../../estilos/mk-auth.css" rel="stylesheet"><link href="../../estilos/font-awesome.css" rel="stylesheet"><link href="../../estilos/bi-icons.css" rel="stylesheet"><script src="../../scripts/jquery.js"></script><script src="../../scripts/mk-auth.js"></script>
<style>.recibo{font:15px system-ui;color:#253748;max-width:1250px;margin:30px auto;padding:0 18px}.recibo section{padding:24px;border:1px solid #d9e3ea;border-radius:12px;background:white;margin:20px 0;box-shadow:0 3px 14px #152f4410}.recibo h1{font-size:25px}.recibo h2{font-size:19px}.recibo label{display:block;margin:15px 0 6px}.recibo input:not([type=checkbox]),.recibo textarea{box-sizing:border-box;width:100%;padding:11px;border:1px solid #bccbd5;border-radius:6px;font:inherit}.recibo textarea{min-height:330px}.recibo button{padding:10px 16px;border:0;border-radius:6px;background:#15895b;color:white;cursor:pointer;margin:8px 8px 0 0;font:inherit}.recibo button:disabled{opacity:.5;cursor:wait}.recibo .secondary{background:#42647e}.recibo .warning{color:#9b4b00}.recibo .hint{color:#596e7d;font-size:14px}.recibo table{border-collapse:collapse;width:100%;font-size:13px}.recibo th,.recibo td{text-align:left;padding:10px;border-bottom:1px solid #dde5eb}.recibo th{background:#eaf3ee}.recibo pre{white-space:pre-wrap;word-break:break-word;max-height:320px;overflow:auto;background:#f3f6f8;padding:15px}.recibo code{word-break:break-word}.recibo #feedback{position:fixed;bottom:20px;right:24px;max-width:650px;background:#16374b;color:white;padding:16px;border-radius:8px;z-index:9999}.recibo #feedback:empty{display:none}.recibo .scroll{overflow:auto}</style></head><body>
<?php include __DIR__.'/../../topo.php'; ?>
<main class="recibo"><h1>Recibo Evolution</h1><p>Confirmações de pagamento pelo WhatsApp · instalação e captura de pagamentos separadas da página.</p>
<?php if($error):?><p class="warning"><?=rh($error)?></p><?php endif;?>
<section><h2>Resumo</h2><p><?php foreach($labels as $k=>$label)echo rh($label).': <strong>'.rh(isset($summary[$k])?$summary[$k]:0).'</strong> &nbsp; ';?></p><p class="hint">A página mostra no máximo os 100 registros mais recentes. “Aceito pela API” não comprova leitura ou entrega no destinatário.</p><button type="button" onclick="document.getElementById('templateBox').hidden=false;document.getElementById('templateBox').scrollIntoView({behavior:'smooth'})">Editar template da mensagem</button></section>
<form id="settings" method="post" action="api.php"><input type="hidden" name="csrf" value="<?=rh($_SESSION['recibo_csrf'])?>"><input type="hidden" name="action" value="save">
<section><h2>Conexão e agendamento</h2><label>URL da API<input name="api_url" value="<?=rh($s['api_url'])?>" required placeholder="http://127.0.0.1:7070"></label><label>Nome da instância<input name="instance" value="<?=rh($s['instance'])?>" required maxlength="100"></label><label>Token / API Key<input type="password" name="token" autocomplete="new-password" placeholder="<?=empty($s['token'])?'Informe a chave':'Chave salva · vazio mantém o valor atual'?>"></label><label>Nome do provedor<input name="provider" value="<?=rh($s['provider'])?>" maxlength="120"></label><label><input name="enabled" type="checkbox" value="1" <?=$s['enabled']?'checked':''?>> Ativar envio automático de novos recibos</label><label>Intervalo em minutos<input name="interval" type="number" min="1" max="60" value="<?=rh($s['interval'])?>"></label><p class="hint">O cron verifica a cada minuto, respeitando o intervalo escolhido. Execuções concorrentes são bloqueadas. Só processa pagamentos capturados pela fila do addon.</p><button type="submit">Salvar configurações</button></section>
<section id="templateBox" hidden><h2>Template do recibo</h2><p class="hint">Campos disponíveis: <code>{cliente} {cpf_cnpj} {id_pagamento} {data_pagamento} {data_vencimento} {valor} {valor_pago} {coletor} {forma_pagamento} {provedor}</code>.</p><textarea name="template" id="template" required><?=rh($s['template'])?></textarea><button type="button" id="preview">Pré-visualizar sem enviar</button><button type="submit">Salvar template</button><pre id="previewText" hidden></pre></section></form>
<section><h2>Processamento</h2><button type="button" id="run">Enviar próximo recibo pendente</button><button type="button" class="secondary" id="refresh">Atualizar página</button><p class="warning">Ações manuais enviam apenas um recibo por vez. Registros em revisão não são reenviados automaticamente: uma falha de rede pode ter acontecido depois de a API aceitar a mensagem.</p></section>
<section><h2>Últimos registros</h2><div class="scroll"><table><thead><tr><th>ID</th><th>Registro</th><th>Login</th><th>Pagamento</th><th>Valor pago</th><th>Estado</th><th>HTTP</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=rh($r['id'])?></td><td><?=rh($r['data'])?></td><td><?=rh($r['login'])?></td><td><?=rh($r['datapag'])?></td><td>R$ <?=rh(number_format($r['valorpag'],2,',','.'))?></td><td><?=rh(isset($labels[$r['envio']])?$labels[$r['envio']]:'Desconhecido')?></td><td><?=rh($r['http_code'])?></td><td><?php if(in_array((int)$r['envio'],array(2,3),true)):?><button type="button" class="secondary" data-retry="<?=rh($r['id'])?>">Revisar e recolocar</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section><h2>Log recente</h2><p class="hint">Visualização limitada aos últimos 64 KiB. Os logs são rotacionados; nenhuma limpeza automática de pagamentos pendentes é executada.</p><button type="button" class="secondary" id="clear">Limpar log</button><pre><?=rh(recibo_tail(RECIBO_DATA.'/log_pagamentos.txt'))?></pre></section><p id="feedback" role="status"></p></main>
<?php include __DIR__.'/../../baixo.php'; ?><script src="../../menu.js.hhvm"></script>
<script>
const form=document.getElementById('settings'),csrf=form.elements.csrf.value;function feedback(s){document.getElementById('feedback').textContent=s}
async function request(data,button){if(button){button.disabled=true}try{const r=await fetch('api.php',{method:'POST',body:data});const o=await r.json();if(!r.ok)throw Error(o.error||'Falha na operação');feedback(o.message||'Concluído.');return o}catch(e){feedback(e.message);throw e}finally{if(button)button.disabled=false}}
function payload(action){const d=new FormData();d.set('csrf',csrf);d.set('action',action);return d}
form.onsubmit=e=>{e.preventDefault();request(new FormData(form),e.submitter||form.querySelector('button')).catch(()=>{})};
document.getElementById('preview').onclick=async function(){const d=payload('preview');d.set('template',form.elements.template.value);try{const o=await request(d,this),p=document.getElementById('previewText');p.textContent=o.preview;p.hidden=false;feedback('Prévia de exemplo. Nenhuma mensagem foi enviada.')}catch{}};
document.getElementById('run').onclick=async function(){if(!confirm('Enviar o próximo recibo pendente pela instância configurada? Confira o número conectado.'))return;try{await request(payload('run'),this)}catch{}};
document.getElementById('refresh').onclick=()=>location.reload();document.getElementById('clear').onclick=function(){if(confirm('Limpar somente o arquivo de log do addon?'))request(payload('clear_log'),this).then(()=>location.reload()).catch(()=>{})};
document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{if(!confirm('Confira o envio anterior. Recolocar pode gerar duplicidade se o cliente já recebeu. Deseja continuar?'))return;const d=payload('retry');d.set('id',b.dataset.retry);d.set('confirm_retry','1');request(d,b).then(()=>location.reload()).catch(()=>{})});
</script></body></html>
